<?php
namespace App\Services;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CcsPaymentReversal{
public function reverse(Request $r,int $id):void{$rules=app(CcsHumanRules::class);$d=$r->validate(['reason'=>'required|string|min:5|max:1000','confirmation'=>'required|accepted','request_token'=>'required|uuid']);$p=DB::table('payments')->find($id);abort_unless($p,404);if((float)$p->amount_lkr<=0)$rules->fail('reason','Only an original positive payment can be reversed.');if(DB::table('ccs_payment_reversals')->where('payment_id',$id)->exists())return;$approval=$rules->approve($r,'payment_reversal',['payment_id'=>$id,'invoice_id'=>$p->invoice_id,'amount'=>$p->amount_lkr,'reason'=>$d['reason']]);DB::transaction(function()use($r,$id,$d,$p,$rules,$approval){$rules->lock();if(DB::table('ccs_payment_reversals')->where('payment_id',$id)->exists())return;$invoice=DB::table('invoices')->where('id',$p->invoice_id)->lockForUpdate()->first();if(!$invoice||!in_array($invoice->status,['issued','partially_paid','paid'],true))$rules->fail('reason','Only a finalized, nonvoid invoice payment can be reversed.');DB::table('payments')->insert(['invoice_id'=>$invoice->id,'amount_lkr'=>number_format(-(float)$p->amount_lkr,2,'.',''),'method'=>$p->method,'reference'=>mb_substr('Reversal #'.$id.': '.$d['reason'],0,100),'request_token'=>$d['request_token'],'received_by_user_id'=>$r->user()->id,'paid_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('ccs_payment_reversals')->insert(['payment_id'=>$id,'recorded_by'=>$r->user()->id,'reason'=>$d['reason'],'created_at'=>now(),'updated_at'=>now()]);$paid=DB::table('payments')->where('invoice_id',$invoice->id)->sum('amount_lkr');DB::table('invoices')->where('id',$invoice->id)->update(['status'=>$paid>=$invoice->total_lkr?'paid':($paid>0?'partially_paid':'issued'),'is_credit_sale'=>$paid<$invoice->total_lkr,'updated_at'=>now()]);$rules->consume($approval,$r->user()->id);app(CcsAdministration::class)->audit($r->user()->id,'payment_reversed','payment',$id,['invoice_id'=>$invoice->id,'reason'=>$d['reason']]);});}
}
